(4733, 2, '2021-10-06 13:30:10', '2021-10-06 13:30:10', '[column_third]\n\n[caption id=\"attachment_4292\" align=\"alignnone\" width=\"146\"]<a href=\"http://www.pec.org.pk/\" target=\"_blank\" rel=\"noopener noreferrer\"><img class=\"wp-image-4292\" src=\"https://barqaab.com.-content/uploads/2014/11/PEC-150x150.jpg\" alt=\"Pakistan Engineering Council\" width=\"146\" height=\"162\" /></a> Pakistan Engineering Council[/caption]\n\n[/column_third]\n\n[column_third]\n\n[caption id=\"attachment_4293\" align=\"alignnone\" width=\"150\"]<img class=\"wp-image-4293 size-thumbnail\" src=\"https://www.barqaab.com.pk/wp-content/uploads/2014/11/ISO_registration-e1633527002235-150x119.jpg\" alt=\"ISO 9001:2008\" width=\"150\" height=\"119\" /> ISO 9001:2015[/caption]\n\n[/column_third]\n\n[column_third]\n\n[caption id=\"attachment_4294\" align=\"alignnone\" width=\"150\"]<a href=\"http://www.acep.org.pk/\" target=\"_blank\" rel=\"noopener noreferrer\"><img class=\"wp-image-4294 size-thumbnail\" src=\"https://barqaab.com.-content/uploads/2014/11/acep-150x150.jpg\" alt=\"Association of Consulting Engineers (Pakistan)\" width=\"150\" height=\"150\" /></a> Association of Consulting Engineers (Pakistan)[/caption]\n\n[/column_third]', 'Registration and Accreditations', '', 'inherit', 'closed', 'closed', '', '4291-revision-v1', '', '', '2021-10-06 13:30:10', '2021-10-06 13:30:10', '', 4291, 'https://www.barqaab.com.pk/2021/10/4291-revision-v1/', 0, 'revision', '', 0),
(4732, 2, '2021-10-06 13:28:54', '2021-10-06 13:28:54', '[column_third]\n\n[caption id=\"attachment_4292\" align=\"alignnone\" width=\"146\"]<a href=\"http://www.pec.org.pk/\" target=\"_blank\" rel=\"noopener noreferrer\"><img class=\"wp-image-4292\" src=\"https://barqaab.com.-content/uploads/2014/11/PEC-150x150.jpg\" alt=\"Pakistan Engineering Council\" width=\"146\" height=\"162\" /></a> Pakistan Engineering Council[/caption]\n\n[/column_third]\n\n[column_third]\n\n[caption id=\"attachment_4293\" align=\"alignnone\" width=\"150\"]<img class=\"wp-image-4293 size-thumbnail\" src=\"https://barqaab.com.-content/uploads/2014/11/ISO_registration-150x150.jpg\" alt=\"ISO 9001:2008\" width=\"150\" height=\"150\" /> ISO 9001:2015[/caption]\n\n[/column_third]\n\n[column_third]\n\n[caption id=\"attachment_4294\" align=\"alignnone\" width=\"150\"]<a href=\"http://www.acep.org.pk/\" target=\"_blank\" rel=\"noopener noreferrer\"><img class=\"wp-image-4294 size-thumbnail\" src=\"https://barqaab.com.-content/uploads/2014/11/acep-150x150.jpg\" alt=\"Association of Consulting Engineers (Pakistan)\" width=\"150\" height=\"150\" /></a> Association of Consulting Engineers (Pakistan)[/caption]\n\n[/column_third]', 'Registration and Accreditations', '', 'inherit', 'closed', 'closed', '', '4291-revision-v1', '', '', '2021-10-06 13:28:54', '2021-10-06 13:28:54', '', 4291, 'https://www.barqaab.com.pk/2021/10/4291-revision-v1/', 0, 'revision', '', 0),
